1: /**
2:  * Remote entries built by `@openmrs/rspack-config` or `@openmrs/webpack-config` read the Module
3:  * Federation runtime from globals instead of embedding a copy each, so the app shell has to publish it.
4:  *
5:  * `@module-federation/runtime-core` is published by Module Federation itself, via the runtime plugin
6:  * that `experiments.provideExternalRuntime` injects. Because it is this build's copy, its compiled-in
7:  * build identifier and `experiments.optimization` settings are the ones every app's federation instance
8:  * ends up with. The two helpers below are published here because that doesn't cover them; they hold no
9:  * cross-build state. `@module-federation/runtime` and `webpack-bundler-runtime` are deliberately not
10:  * published — they cache a federation instance at module scope, so a remote using the app shell's copy
11:  * dies with RUNTIME-010.
12:  */
13: import * as errorCodes from '@module-federation/error-codes';
14: import * as sdk from '@module-federation/sdk';
15: 
16: declare global {
17:   // `var` is what declares a property on `globalThis`; `let`/`const` do not.
18:    
19:   var _OPENMRS_FEDERATION_ERROR_CODES: typeof errorCodes;
20:    
21:   var _OPENMRS_FEDERATION_SDK: typeof sdk;
22:    
23:   var _FEDERATION_RUNTIME_CORE: unknown;
24: }
25: 
26: /**
27:  * A function rather than a module side effect so the call can't be tree-shaken away if the app shell
28:  * ever declares `sideEffects: false`.
29:  */
30: export function publishFederationRuntime() {
31:   globalThis._OPENMRS_FEDERATION_ERROR_CODES = errorCodes;
32:   globalThis._OPENMRS_FEDERATION_SDK = sdk;
33: 
34:   // Reporting this here means a mis-built app shell says so itself, rather than every app in the
35:   // distribution claiming the app shell is too old.
36:   if (typeof globalThis._FEDERATION_RUNTIME_CORE === 'undefined') {
37:     console.error(
38:       'The app shell did not publish the Module Federation runtime, so no frontend module will be able ' +
39:         'to start. This is a bug in the app shell build (see `experiments.provideExternalRuntime`).',
40:     );
41:   }
42: }
